CREATE OR REPLACE SECURE VIEW DP_GENERATION.OUT_STORAGE_STATUS
  WITH TAG (GOV.DATA_CLASSIFICATION = 'Internal - Restricted', GOV.DATA_OWNER = 'Energy Data Engineering Team', GOV.DOMAIN = 'Energy_Generation_Package')
  COMMENT = 'Atomic contracted output for StorageAsset'
AS
SELECT f.STORAGE_STATUS_ID, f.STORAGE_ASSET_ID, f.DATE_KEY, f.SOURCE_ID, f.POWER_PLANT_ID, f.DISCHARGE_RATE_MW, f.STATE_OF_CHARGE_PCT, d1.ASSET_NAME, d1.STORAGE_CAPACITY_MWH, d2.FISCAL_YEAR, d2.FULL_DATE, d2.IS_HOLIDAY, d2.IS_WEEKEND, d2.MONTH_NAME, d2.MONTH_NUMBER, d2.QUARTER, d3.IS_REC_ELIGIBLE, d3.SOURCE_CATEGORY, d3.SOURCE_NAME, d4.PLANT_NAME, d4.PLANT_TYPE, d4.REGION
FROM CORE.FCT_STORAGE_STATUS f
LEFT JOIN CORE.DIM_STORAGE_ASSET d1 ON f.STORAGE_ASSET_ID = d1.STORAGE_ASSET_ID
LEFT JOIN CORE.DIM_DATE d2 ON f.DATE_KEY = d2.DATE_KEY
LEFT JOIN CORE.DIM_ENERGY_SOURCE d3 ON f.SOURCE_ID = d3.SOURCE_ID
LEFT JOIN CORE.DIM_POWER_PLANT d4 ON f.POWER_PLANT_ID = d4.POWER_PLANT_ID;
